def buscar(nombre):
    for ext in ("png", "jpg", "jpeg", "webp"):
        f = BASE / f"{nombre}.{ext}"
        if f.exists():
            return f
    return None


def data_uri(f):
    ext = f.suffix.lower().strip(".")
    ext = "jpeg" if ext == "jpg" else ext
    return f"data:image/{ext};base64," + base64.b64encode(f.read_bytes()).decode()


