# ----------------------------- Exportar ficha de evidencia a Word -----------------------------
def generar_docx(nombre, rgb, anot, df, glob, zrms, fig_radar, fig_z, usar_ref):
    from docx import Document
    from docx.shared import Inches, Pt, RGBColor
    from docx.enum.text import WD_ALIGN_PARAGRAPH

    def png(arr):
        b = io.BytesIO(); Image.fromarray(arr).save(b, "PNG"); b.seek(0); return b

    def figpng(fig):
        b = io.BytesIO(); fig.savefig(b, format="png", dpi=150, bbox_inches="tight"); b.seek(0); return b

    verde = RGBColor.from_string(COLOR_1.strip("#").upper())
    d = Document()
    d.styles["Normal"].font.name = "Calibri"
    d.styles["Normal"].font.size = Pt(11)

    t = d.add_table(rows=1, cols=2)
    a, b = t.rows[0].cells
    a.paragraphs[0].add_run().add_picture(io.BytesIO(base64.b64decode(LOGO_UNI_B64)), width=Inches(1.0))
    b.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.RIGHT
    b.paragraphs[0].add_run().add_picture(io.BytesIO(base64.b64decode(LOGO_CARRERA_B64)), width=Inches(1.0))

    for txt, size, bold in [(UNIVERSIDAD, 14, True), (f"{FACULTAD} - {CARRERA}", 11, False)]:
        p = d.add_paragraph(); p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        r = p.add_run(txt); r.bold = bold; r.font.size = Pt(size); r.font.color.rgb = verde

    h = d.add_heading("Ficha de evidencia - Análisis morfométrico facial", level=1)
    h.alignment = WD_ALIGN_PARAGRAPH.CENTER
    d.add_paragraph(f"Fecha y hora: {datetime.now():%d/%m/%Y %H:%M}   |   Imagen analizada: {nombre}")

    d.add_heading("1. Imagen enviada y detección", level=2)
    t = d.add_table(rows=2, cols=2)
    for i, (arr, leyenda) in enumerate([(rgb, "Imagen enviada"), (anot, "Landmarks y medidas detectados")]):
        c = t.rows[0].cells[i]; c.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
        c.paragraphs[0].add_run().add_picture(png(arr), height=Inches(2.9))
        l = t.rows[1].cells[i].paragraphs[0]; l.alignment = WD_ALIGN_PARAGRAPH.CENTER
        l.add_run(leyenda).italic = True

    d.add_heading("2. Resultado", level=2)
    nivel = "ALTA" if glob >= 75 else "MEDIA" if glob >= 50 else "BAJA"
    p = d.add_paragraph()
    p.add_run("Similitud global con el perfil de referencia: ").bold = True
    r = p.add_run(f"{glob:.1f} % ({nivel})"); r.bold = True; r.font.color.rgb = verde
    d.add_paragraph(f"Distancia z-RMS: {zrms:.2f}. Perfil usado: "
                    + ("foto de poblador amazónico de referencia." if usar_ref else "valores manuales."))

    d.add_heading("3. Detalle por medida", level=2)
    tb = d.add_table(rows=1, cols=7); tb.style = "Light Grid Accent 1"
    for c, tx in zip(tb.rows[0].cells, ["Medida", "Valor", "μ ref.", "σ", "z", "Similitud %", "Peso"]):
        c.text = tx
    for _, r in df.iterrows():
        cs = tb.add_row().cells
        for c, tx in zip(cs, [r.metrica, f"{r.valor:.3f}", f"{r.media:.3f}", f"{r.desv:.3f}",
                              f"{r.z:+.2f}", f"{r.similitud:.1f}", f"{r.peso:.1f}"]):
            c.text = tx

    d.add_heading("4. Gráficos", level=2)
    for fig, w in [(fig_radar, 3.6), (fig_z, 5.2)]:
        p = d.add_paragraph(); p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.add_run().add_picture(figpng(fig), width=Inches(w))

    d.add_heading("5. Fórmulas utilizadas", level=2)
    d.add_paragraph("z = (x - μ) / σ      Sᵢ = 100·exp(-zᵢ²/2)      S = Σ(wᵢ·Sᵢ) / Σ wᵢ")
    d.add_paragraph("Nota: el resultado expresa similitud de proporciones faciales con un perfil de "
                    "referencia; no constituye una clasificación étnica o racial de la persona.")
    out = io.BytesIO(); d.save(out)
    return out.getvalue()


